    "ponente": "niihfqcoynlazghdtqtqx",
    "activo": false,
    "imagen_url": "http:\/\/www.adams.com\/"
};

fetch(url, {
    method: "PUT",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

